mapper.update:

        /*updateSelectedDataGrNextMonth_1*/
			UPDATE DB_OFF_IV A	
               SET A.DS_QTY=DECODE( NVL( A.GR_QTY, 0), 0, ${st_gr_qty}, A.GR_QTY),    
                   A.PO_QTY=DECODE( NVL( A.GR_QTY, 0), 0, ${st_gr_qty}, A.GR_QTY),    
                   A.GR_QTY=DECODE( NVL( A.GR_QTY, 0), 0, ${st_gr_qty}, A.GR_QTY),
                   A.GR_DATE = #{st_gr_date},
				   A.GR_USER_ID =#{st_user_id},
				   A.BTOA_REMARK = #{st_remark},
			   	   A.REASON_REMARK=#{st_remark}	

			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=#{st_seq}		
			   AND A.DS_SEQ=#{st_ds_seq}


        /*updateSelectedDataGrNextMonth_3*/
			UPDATE DB_OFF_PO A	
			   SET A.DO_QTY=A.DO_QTY-${st_next_po_qty},	
				   A.IV_QTY=A.IV_QTY-${st_next_po_qty},	
				   A.CHANGE_DATE=TO_CHAR(SYSDATE, 'YYYYMMDD'),	
				   A.CHANGE_TIME=TO_CHAR(SYSDATE, 'HH24MISS')	
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=#{st_seq}


        /*updateSelectedDataGrCancelReg_1*/
			UPDATE DB_OFF_IV A					
			   SET A.GR_DATE=NULL,				
			   	   A.GR_QTY=NVL(A.GR_QTY,0)-${st_gr_qty},	
				   A.CLOSE_FLAG='N',			
				   A.GR_USER_ID=NULL,			
				   A.GR_ADD_DATE=NULL,			
				   A.GR_ADD_TIME=NULL			
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=#{st_seq}		
			   AND A.DS_SEQ=#{st_ds_seq}


        /*updateSelectedDataGrCancelReg_2*/
			UPDATE DB_OFF_PO A	
			   SET A.GR_QTY=NVL(A.GR_QTY,0)-${st_gr_qty}	
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=#{st_seq}


        /*updateSelectedDataGrRegBuyer_1*/
			UPDATE DB_OFF_IV A					
			   SET A.GR_DATE=#{st_gr_date},					
			   	   A.GR_QTY=NVL(A.GR_QTY,0)+${st_gr_qty},	
				   A.GR_USER_ID=#{st_user_id},				
				   A.CLOSE_FLAG='Y',			
				   A.GR_ADD_DATE=TO_CHAR(SYSDATE, 'YYYYMMDD'),	
				   A.GR_ADD_TIME=TO_CHAR(SYSDATE, 'HH24MISS')	

			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=#{st_seq}		
			   AND A.DS_SEQ=#{st_ds_seq}


        /*updateSelectedDataGrRegBuyer_2*/
			UPDATE DB_OFF_PO A	
			   SET A.GR_QTY=NVL(A.GR_QTY,0)+${st_gr_qty},	
			   A.CLOSE_FLAG=DECODE((SELECT COUNT(*) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D' AND CLOSE_FLAG='N'),0,'Y','N')	
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=#{st_seq}
